SELECT

FROM shop_store_investment i

    i.is_deleted = 0


        AND (i.investment_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR i.applicant_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR i.applicant_phone LIKE CONCAT('%', #{q.keyword}, '%'))


        AND i.intent_type = #{q.intentType}


        AND i.source = #{q.source}


        AND i.status = #{q.status}




        AND i.sign_time >= #{q.beginTime}


        AND i.sign_time <= #{q.endTime}



ORDER BY i.id DESC
